-- ============================================================================
-- Migration 006: Add missing audit action values to CHECK constraint
-- ============================================================================
-- PROBLEM: AdminController::userManagement writes audit action
--   'user_created_by_admin' which is not in chk_audit_logs_action.
--   Similar mismatches exist for 7 other actions used in the codebase.
--   Production returns 4025 CONSTRAINT violation → 500 error.
--
-- FIX: Two-pronged approach:
--   A. Backend code fix (AdminController.php): Changed
--      'user_created_by_admin' → 'user_created' (already in constraint)
--      'user_permanently_deleted' → 'user_hard_deleted' (already in constraint)
--      'trash_cleanup_manual' → 'trash_emptied' (already in constraint)
--   B. Database fix (this migration): Add 8 genuinely new actions that are
--      intentionally used by application code but missing from the constraint.
--
-- Missing actions added:
--   1. admin_action              (RpcController — generic admin operation)
--   2. codes_batch_cloned        (CreditController — batch code cloning)
--   3. codes_batch_created       (CreditController — batch code creation)
--   4. codes_bulk_deleted        (CreditController — bulk code deletion)
--   5. codes_deactivated         (CreditController — code deactivation)
--   6. codes_reactivated         (CreditController — code reactivation)
--   7. orphan_video_cleanup      (VideoController — orphan video removal)
--   8. student_removed_from_course (RpcController — enrollment removal)
--
-- HOW TO USE:
--   Import this file as-is on any environment where chk_audit_logs_action exists.
--   It drops the old constraint and re-adds it with the full value list.
--
-- No rows are modified. Only the CHECK constraint is replaced.
-- ============================================================================


-- ════════════════════════════════════════════════════════════════════════════
-- BLOCK A — DROP + re-ADD (normal case where constraint exists)
-- ════════════════════════════════════════════════════════════════════════════
ALTER TABLE `audit_logs` DROP CONSTRAINT `chk_audit_logs_action`;

ALTER TABLE `audit_logs` ADD CONSTRAINT `chk_audit_logs_action` CHECK (`action` IN ('login', 'logout', 'register', 'password_reset', 'course_created', 'course_updated', 'course_deleted', 'lesson_created', 'lesson_updated', 'lesson_deleted', 'video_uploaded', 'pdf_uploaded', 'pdf_deleted', 'credit_allocated', 'credit_consumed', 'credit_deducted', 'code_created', 'code_redeemed', 'code_deactivated', 'device_reset', 'device_force_logout', 'role_changed', 'permission_changed', 'user_suspended', 'user_activated', 'enrollment_created', 'security_event', 'initial_super_admin_created', 'password_changed', 'phone_login', 'user_searched', 'user_created', 'admin_created', 'super_admin_created', 'device_blocked', 'device_unblocked', 'device_registered', 'limit_changed', 'unlimited_enabled', 'unlimited_disabled', 'device_logout_all', 'device_revoked', 'user_deleted', 'student_created_by_doctor', 'student_bulk_imported', 'course_assigned_by_doctor', 'credit_consumed_by_doctor', 'temp_password_generated', 'password_changed_first_login', 'root_detected', 'jailbreak_detected', 'vpn_detected', 'proxy_detected', 'ssl_pinning_failure', 'screenshot_detected', 'screen_recording_detected', 'debug_detected', 'frida_detected', 'xposed_detected', 'app_integrity_compromised', 'security_policy_changed', 'user_trashed', 'user_restored', 'bulk_trash', 'bulk_restore', 'user_hard_deleted', 'bulk_permanent_delete', 'device_removed', 'undo_delete', 'trash_emptied', 'system_health_check', 'provider_changed', 'device_limit_changed', 'unlimited_devices_enabled', 'unlimited_devices_disabled', 'bulk_suspend', 'bulk_unsuspend', 'bulk_reset_devices', 'bulk_reset_password', 'account_restored', 'deletion_verification_failed', 'impersonation_started', 'impersonation_ended', 'code_deleted', 'video_play', 'video_play_failed', 'credit_refunded', 'credit_expired', 'subscription_created', 'subscription_removed', 'subscription_restored', 'profile_updated', 'avatar_updated', 'settings_changed', 'enrollment_created_b